(() => {
  'use strict';
  let api,tab='review',showDone=false;
  let store={done:[],drafts:[],workflows:[
    {id:'welcome',name:'A second invitation',trigger:'First visit',delay:7,channel:'SMS',template:'Hi {first_name}, thank you for joining us. Would you like to come back for another garden shift? Reply if you would like a hand finding a date. Reply STOP to opt out.'},
    {id:'reminder',name:'Before the next shift',trigger:'Upcoming event',delay:1,channel:'Email',template:'Hi {first_name}, a quick reminder about your upcoming community shift. We look forward to seeing you.'},
    {id:'match',name:'An opportunity that fits',trigger:'New opportunity match',delay:0,channel:'Email',template:'Hi {first_name}, we found an opportunity that may fit your interests. We will confirm the details before inviting you to take part.'}
  ]};
  try{const saved=JSON.parse(localStorage.getItem('roots-notices-v1')||'{}');store={...store,...saved};}catch{}
  const e=s=>api.esc(s);
  function save(){try{localStorage.setItem('roots-notices-v1',JSON.stringify(store));}catch{api.toast('Browser storage unavailable. Changes last for this visit.');}window.RootsBridge?.sync();}
  function notices(){const people=api.getState().people,first=people.filter(p=>p.visits===1),service=people.filter(p=>p.interests.includes('Service hours')),noConsent=people.filter(p=>!p.consent);return [
    {id:'return',title:`${first.length} people are ready for a second invitation.`,description:'A personal invitation to a relevant shift can make the next visit easier.',kind:'Engagement',people:first.map(p=>p.id),action:'Review invitation',icon:'message'},
    {id:'benefit',title:'Put volunteer benefits in front of the right people.',description:`${service.length} profiles mention service hours. Check placement requirements, then share a suitable lead.`,kind:'Opportunity match',people:service.map(p=>p.id),action:'Explore matches',icon:'graduation'},
    {id:'lead',title:'A project needs a person to bring it together.',description:'The garden plan has useful skills in the community. Review a possible team and name a lead.',kind:'Project readiness',people:people.filter(p=>p.interests.includes('Carpentry')).map(p=>p.id),action:'Review project',icon:'sprout'},
    {id:'consent',title:'Keep communication preferences up to date.',description:`${noConsent.length} profiles have no SMS permission recorded. They stay out of SMS workflow previews.`,kind:'People',people:noConsent.map(p=>p.id),action:'Review people',icon:'users'}
  ].map(n=>({...n,status:store.done.includes(n.id)?'Reviewed':'New'}));}
  function refresh(focus){api.render();if(focus)document.querySelector(focus)?.focus({preventScroll:true});}
  function tabs(){const draftCount=store.drafts.length+(window.RootsBridge?.activity?.drafts?.length||0);return `<div class="platform-tabs" role="group" aria-label="Notices view">${[['review','To review'],['drafts','Drafts'],['workflows','Workflows']].map(([key,label])=>`<button data-notice="tab" data-tab="${key}" class="${tab===key?'active':''}" aria-pressed="${tab===key}">${label}${key==='drafts'&&draftCount?` <span>${draftCount}</span>`:''}</button>`).join('')}</div>`;}
  function render(){return `${api.head('A little nudge. A useful next step.','Recommendations, thoughtful outreach, and the routines that keep your community moving.')} ${tabs()}${tab==='review'?review():tab==='drafts'?draftList():tab==='workflows'?workflows():assistant()}`;}
  function review(){const rows=notices().filter(n=>showDone?n.status==='Reviewed':n.status!=='Reviewed');return `<div class="notice-toolbar"><span class="tiny-label">${rows.length} ${showDone?'reviewed':'suggested'} next steps</span><button class="button quiet" data-notice="done-filter">${showDone?'Show new notices':'Show reviewed'}</button></div><div class="notice-list">${rows.map(n=>`<article class="notice-row"><span class="notice-symbol">${api.icon(n.icon)}</span><div class="notice-content"><span class="notice-kind">${e(n.kind)}</span><h2>${e(n.title)}</h2><p>${e(n.description)}</p><div class="notice-people">${n.people.slice(0,4).map(id=>{const p=api.getState().people.find(x=>x.id===id);return `<button data-notice="person" data-id="${id}" aria-label="View ${e(p.name)}">${api.avatar(p)}</button>`;}).join('')}<span>${n.people.length} relevant people</span></div></div><div class="notice-actions"><button class="button" data-notice="open" data-id="${n.id}">${e(n.action)} ${api.icon('arrow')}</button><button class="button quiet" data-notice="complete" data-id="${n.id}">${n.status==='Reviewed'?'Mark as new':'Mark reviewed'}</button></div></article>`).join('')}</div>${!rows.length?'<div class="empty"><h3>You’re up to date.</h3><p>New suggestions will appear when there is something useful to act on.</p></div>':''}<p class="platform-footnote">Illustrative recommendations from the demo records. A connected assistant can help you explore them; nothing is sent automatically.</p>`;}
  function draftList(){const remote=window.RootsBridge?.activity?.drafts||[];return `<div class="notice-toolbar"><span class="tiny-label">Saved for a human to review</span><div class="notice-actions">${window.RootsBridge?.status?.connected?'<button class="button quiet" data-notice="refresh-drafts">Refresh</button>':''}<button class="button" data-notice="compose">${api.icon('plus')} New draft</button></div></div>${store.drafts.length||remote.length?`<div class="draft-list">${store.drafts.map(d=>`<article class="draft-row"><div><span class="badge neutral">${e(d.channel)} draft</span><h3>${e(d.title||d.recipients.map(id=>api.getState().people.find(p=>p.id===id)?.name||'Volunteer').join(', '))}</h3><p>${e(d.message)}</p><small>${d.recipients.length} ${d.recipients.length===1?'recipient':'recipients'} · Not sent</small></div><button class="button quiet" data-notice="edit-draft" data-id="${d.id}">Review ${api.icon('arrow')}</button></article>`).join('')}${remote.map(d=>`<article class="draft-row"><div><span class="badge neutral">Assistant draft</span><h3>${e(d.personName||d.person_name||d.recipient||'Volunteer message')}</h3><p>${e(d.message||d.body||'')}</p><small>${e(d.channel||'Message')} · Prepared through the assistant · Not sent${d.contactConsent===false?' · Permission not recorded':''}</small></div><button class="button quiet" data-chat="review-draft" data-id="${e(d.id)}">Review in chat ${api.icon('arrow')}</button></article>`).join('')}</div>`:'<div class="empty"><h3>A thoughtful message starts here.</h3><p>Save an invitation from a notice or a person’s profile.</p></div>'}`;}
  function workflows(){return `<div class="workflow-intro"><div><h2>Make the useful things repeat.</h2><p>Define the audience, timing, and message once. Connect a delivery service before turning on automatic email or SMS.</p></div><span class="badge orange">Delivery not connected</span></div><div class="workflow-list">${store.workflows.map(w=>`<article class="workflow-row"><span class="notice-symbol">${api.icon(w.channel==='SMS'?'message':'refresh')}</span><div><h3>${e(w.name)}</h3><p>${e(w.trigger)} <span>→</span> ${w.delay?`${w.delay} ${w.delay===1?'day':'days'} ${w.trigger==='Upcoming event'?'before':'later'}`:'When matched'} <span>→</span> ${e(w.channel)}</p></div><span class="badge neutral">Draft</span><button class="button quiet" data-notice="workflow" data-id="${w.id}">Configure ${api.icon('arrow')}</button></article>`).join('')}</div><div class="help-banner">${api.icon('info')}Workflow previews show potential recipients only. Activation becomes available when delivery, consent, and timing records are connected.</div>`;}
  function assistant(){const b=window.RootsBridge,status=b?.status;return `<div class="assistant-intro"><div class="assistant-mark">${api.icon('sprout')}</div><h2>A conversation with your community in view.</h2><p>Ask about a person, find a useful opportunity, or prepare a message. The local test shares its dashboard records with Telegram. The published demo is separate until a hosted connection is added.</p></div><div class="assistant-connection"><div><strong>Telegram</strong><p>${status?.telegramErrorCode?'Telegram chat stopped because another bot listener is active.':status?.polling?`Chat with @${e(status.botUsername||'your bot')} using /roots. This local test must stay running.`:status?.telegramConfigured?'Bot credentials are configured for the local test.':'Connect a Roots bot to start a conversation in Telegram.'}</p></div><span class="badge ${status?.polling?'green':'neutral'}">${status?.polling?'Listening':status?.telegramConfigured?'Ready to test':'Not connected'}</span></div><div class="assistant-connection"><div><strong>Gemini</strong><p>${status?.geminiConfigured?'A server-side key is configured. Try a question below.':'An API key is needed on the test server. Keys never belong in this page.'}</p></div><span class="badge ${status?.geminiConfigured?'green':'neutral'}">${status?.geminiConfigured?'Configured':'Not connected'}</span></div><p id="assistant-sync-error" class="hint" role="alert">${status?.syncError?`Dashboard sync failed: ${e(status.syncError)}`:''}</p><section class="assistant-test"><h3>Try the assistant</h3><div class="assistant-suggestions">${['Who has only visited once?','Which opportunities fit Maya Chen?','Draft a welcome-back message for Maya.'].map(q=>`<button data-notice="prompt" data-prompt="${e(q)}">${e(q)}</button>`).join('')}</div><form id="assistant-chat-form"><label class="sr-only" for="assistant-prompt">Ask Roots</label><textarea id="assistant-prompt" name="message" rows="2" maxlength="2000" placeholder="Ask Roots about your community…" required></textarea><button class="button primary" type="submit" ${status?.geminiConfigured?'':'disabled'}>Ask Roots ${api.icon('arrow')}</button></form><p class="hint">${status?.geminiConfigured?'This test can read demo records and prepare drafts. Email and SMS delivery are not enabled.':'Open the local test server with your Gemini configuration to try this. The published demo keeps working without a connection.'}</p><div id="assistant-response" class="assistant-response" role="status" aria-live="polite"></div></section>`;}
  function compose(personId,existingId,group){const people=api.getState().people,existing=store.drafts.find(d=>d.id===existingId);const selected=existing?.recipients||group||(personId?[personId]:[people[0].id]);const channel=existing?.channel||'SMS';const message=existing?.message||`Hi {first_name}, thank you for being part of our community. Would you like to join us for another garden shift? Reply if you would like help finding a date. Reply STOP to opt out.`;api.openDialog('Thoughtful outreach',`<h2 id="dialog-title">${selected.length>1?'An invitation to return.':`A message for ${e(people.find(p=>p.id===selected[0])?.name.split(' ')[0]||'a volunteer')}.`}</h2><p class="lead">Make it relevant, make it personal, and save it for review.</p><form id="notice-draft-form" data-id="${e(existingId||'')}"><div class="form-field"><label for="notice-recipients">Recipients</label><select id="notice-recipients" name="recipients" multiple size="${Math.min(5,people.length)}" required>${people.map(p=>`<option value="${p.id}" ${selected.includes(p.id)?'selected':''}>${e(p.name)}${p.consent?'':' · SMS consent missing'}</option>`).join('')}</select><p class="hint">Select one or more people. SMS drafts exclude people without recorded permission.</p></div><div class="form-field"><label for="notice-channel">Channel</label><select id="notice-channel" name="channel"><option ${channel==='SMS'?'selected':''}>SMS</option><option ${channel==='Email'?'selected':''}>Email</option></select></div><div class="form-field"><label for="notice-message">Message</label><textarea name="message" id="notice-message" required maxlength="2000">${e(message)}</textarea><p class="hint">Use {first_name} to personalize each draft.</p></div><button class="button primary wide" type="submit">Save draft</button><p class="source-note">No message is sent. Email permission and delivery details must be verified before sending.</p></form>`);}
  function workflow(id){const w=store.workflows.find(x=>x.id===id);api.openDialog('Automated workflow',`<h2 id="dialog-title">${e(w.name)}</h2><p class="lead">Set the rule, then preview who it would reach.</p><form id="workflow-form" data-id="${w.id}"><div class="form-field"><label for="workflow-name">Workflow name</label><input id="workflow-name" name="name" value="${e(w.name)}" required maxlength="80"></div><div class="form-field"><label for="workflow-trigger">When</label><select id="workflow-trigger" name="trigger">${['First visit','Upcoming event','New opportunity match'].map(t=>`<option ${w.trigger===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-row"><div class="form-field"><label for="workflow-delay">Days ${w.trigger==='Upcoming event'?'before':'after'}</label><input id="workflow-delay" name="delay" type="number" min="0" max="90" value="${w.delay}" required></div><div class="form-field"><label for="workflow-channel">Channel</label><select id="workflow-channel" name="channel"><option ${w.channel==='SMS'?'selected':''}>SMS</option><option ${w.channel==='Email'?'selected':''}>Email</option></select></div></div><div class="form-field"><label for="workflow-template">Message template</label><textarea id="workflow-template" name="template" required maxlength="2000">${e(w.template)}</textarea></div><button class="button primary wide" type="submit">Save workflow draft</button></form><section class="dialog-section"><h3>Before it can run automatically</h3><p>Connect an email or SMS delivery provider, verify recipient permission, and confirm event or first-visit timestamps.</p><button class="button wide" data-notice="preview-workflow" data-id="${w.id}">Preview audience</button></section><div id="workflow-preview"></div>`);}
  function previewWorkflow(){
    const form=document.getElementById('workflow-form');
    if(!form.reportValidity())return;
    const values=new FormData(form),trigger=String(values.get('trigger')),channel=String(values.get('channel')),delay=Number(values.get('delay'));
    const state=api.getState(),matched=new Set(window.RootsOpportunities.list().flatMap(o=>o.matches.map(m=>m.personId)));
    const categories=new Set(state.events.map(event=>event.category));
    const rows=state.people.filter(p=>(trigger==='First visit'?p.visits===1:trigger==='New opportunity match'?matched.has(p.id):p.interests.some(interest=>categories.has(interest)))&&(channel!=='SMS'||p.consent));
    const caveat=trigger==='Upcoming event'?'These interests fit an upcoming event; attendance bookings are not recorded.':trigger==='New opportunity match'?'These profiles match an opportunity; newly matched timestamps are not recorded.':'These profiles have one recorded visit; the exact first-visit date still needs verification.';
    document.getElementById('workflow-preview').innerHTML=`<div class="success-panel"><strong>${rows.length} potential recipients · ${e(channel)}</strong>${rows.slice(0,6).map(p=>e(p.name)).join(', ')}${rows.length>6?'…':''}<p>${e(trigger)} · ${delay} ${delay===1?'day':'days'} ${trigger==='Upcoming event'?'before':'after'}. ${caveat} Delivery permission and timing must be verified before activation.</p></div>`;
  }
  window.addEventListener('roots:activity',()=>{if(api&&api.getState().view==='notices'&&tab==='drafts')refresh();});
  window.addEventListener('roots:connection',()=>{const label=document.getElementById('assistant-sync-error');if(label)label.textContent=window.RootsBridge.status?.syncError?`Dashboard sync failed: ${window.RootsBridge.status.syncError}`:'';});
  document.addEventListener('change',event=>{if(event.target.id==='workflow-trigger')document.querySelector('label[for="workflow-delay"]').textContent=event.target.value==='Upcoming event'?'Days before':'Days after';});
  document.addEventListener('click',event=>{const b=event.target.closest('[data-notice]');if(!b||!api)return;const a=b.dataset.notice;if(a==='tab'){tab=b.dataset.tab;refresh(`[data-notice="tab"][data-tab="${tab}"]`);if(tab==='drafts')window.RootsBridge?.loadActivity().catch(error=>api.toast(error.message));}else if(a==='done-filter'){showDone=!showDone;refresh('[data-notice="done-filter"]');}else if(a==='person')api.showPerson(b.dataset.id);else if(a==='complete'){store.done=store.done.includes(b.dataset.id)?store.done.filter(x=>x!==b.dataset.id):[...store.done,b.dataset.id];save();refresh();api.toast('Notice updated.');}else if(a==='open'){if(b.dataset.id==='return')compose(null,null,api.getState().people.filter(p=>p.visits===1&&p.consent).map(p=>p.id));if(b.dataset.id==='benefit')api.showOpportunity('o01');if(b.dataset.id==='lead')api.showOpportunity('project-garden');if(b.dataset.id==='consent')location.hash='people';}else if(a==='compose')compose();else if(a==='edit-draft')compose(null,b.dataset.id);else if(a==='workflow')workflow(b.dataset.id);else if(a==='refresh-drafts'){window.RootsBridge.loadActivity().catch(error=>api.toast(error.message));}else if(a==='preview-workflow'){previewWorkflow();}else if(a==='prompt'){document.getElementById('assistant-prompt').value=b.dataset.prompt;document.getElementById('assistant-prompt').focus();}});
  document.addEventListener('submit',async event=>{if(event.target.id==='notice-draft-form'){event.preventDefault();const f=new FormData(event.target),channel=String(f.get('channel')),selected=f.getAll('recipients'),recipients=selected.filter(id=>channel!=='SMS'||api.getState().people.find(p=>p.id===id)?.consent),message=String(f.get('message')).trim();if(!recipients.length){api.toast('No recipients have recorded SMS permission. Choose another audience or channel.');return;}if(!message)return;const id=event.target.dataset.id||`draft-${Date.now()}`,draft={id,channel,recipients,message,updatedAt:new Date().toISOString()};store.drafts=[draft,...store.drafts.filter(d=>d.id!==id)];save();api.logActivity('An outreach draft saved for review');api.closeDialog();tab='drafts';location.hash='notices';refresh();api.toast(`Draft saved for ${recipients.length} ${recipients.length===1?'person':'people'}. Nothing sent.`);}else if(event.target.id==='workflow-form'){event.preventDefault();const f=new FormData(event.target),w=store.workflows.find(x=>x.id===event.target.dataset.id);Object.assign(w,{name:String(f.get('name')).trim(),trigger:String(f.get('trigger')),delay:Number(f.get('delay')),channel:String(f.get('channel')),template:String(f.get('template')).trim()});save();api.closeDialog();refresh();api.toast('Workflow draft saved. Automatic delivery is not enabled.');}else if(event.target.id==='assistant-chat-form'){event.preventDefault();const input=document.getElementById('assistant-prompt'),response=document.getElementById('assistant-response'),button=event.target.querySelector('button');button.disabled=true;response.textContent='Roots is looking at your community…';try{const result=await window.RootsBridge.chat(input.value);response.textContent=result.reply;await window.RootsBridge.loadActivity();}catch(err){response.textContent=err.message||'The assistant is unavailable. Check the local test connection.';}finally{button.disabled=!window.RootsBridge?.status?.geminiConfigured;}}});
  window.RootsNotices={configure(callbacks){api=callbacks;},render,compose,notices,workflows:()=>store.workflows,drafts:()=>store.drafts,openTab(value){if(value==='assistant'){location.hash='chat';return;}tab=value;location.hash='notices';refresh();if(tab==='drafts')window.RootsBridge?.loadActivity().catch(error=>api.toast(error.message));}};
})();
